let requestCount = 0;

export async function incrementAndGet(): Promise<number> {
  const current = requestCount;
  await someAsyncWork();
  requestCount = current + 1;
  return requestCount;
}

async function someAsyncWork() {
  await new Promise(resolve => setTimeout(resolve, 10));
}
